function markedText(text,{enabled=false,indexed=false}={}){
 const readings=enabled?(session?.context?.kind==='custom'&&text===session.target?readingDetails(text,{custom:true,edits:session.context.readingEdits||{}}).map(x=>x.reading):jyutpingFor(text)):[],letters=chars(text);
 return letters.map((letter,i)=>{const base=`<span ${indexed?`data-i="${i}"`:''} class="${letter===' '?'space':''}" ${!indexed?`data-base="${i}"`:''}>${esc(letter)}</span>`;return readings[i]?`<ruby>${base}<rt aria-hidden="true">${esc(readings[i])}</rt></ruby>`:base;}).join('');
}
