function articlePool(){return articles.filter(a=>a.lang===state.lang);}
function drawNext(){const ids=articlePool().map(a=>a.id);decks[state.lang]=drawCard(ids,decks[state.lang]);if(!save('decks-v2',decks))toast(t('storageWarning'));return selectedArticle();}
