function dailyCard(){const best=records.filter(r=>r.context?.kind==='daily'&&r.userId===profile?.id&&r.day===challengeDay()&&r.lang===state.lang&&r.online?.qualified).sort((a,b)=>(b.online?.wpm||0)-(a.online?.wpm||0))[0];return `<button class="daily-card" data-action="daily"><span class="daily-icon">${icon('calendar')}</span><div><span class="daily-overline">DAILY CHALLENGE</span><strong>${t('daily')}</strong><p>${t('dailySub')}</p></div><span class="daily-status">${best?`${t('dailyBest')} · ${Math.round(best.online.wpm)} WPM`:t('dailyStart')}${icon('arrow')}</span></button>`;}
