function onlineError(error){return t(({NAME:'nameInvalid',NAME_TAKEN:'nameTaken',IDENTITY:'identityError',EXPIRED:'runExpired',RATE:'tooManyRuns',TRACE:'serverTraceError',INCOMPLETE:'rankIncomplete'})[error.code]||'networkError');}
