 $('#chart-hit').addEventListener('pointermove',show);$('#chart-hit').addEventListener('pointerdown',show);svg.addEventListener('pointerleave',()=>{tip.hidden=true;$('#chart-guide').setAttribute('visibility','hidden');$('#chart-point').setAttribute('visibility','hidden');});
