function handleInline(type){const local=inlineSessions[type];if(!local||local.composing||local.phase==='done')return;const input=$('#inline-input-'+type);const next=input.value.normalize('NFC').replace(/\n/g,'');if(next===local.typed)return;if(!local.started){local.started=performance.now();local.phase='running';}const added=insertedAttempts(local.typed,next,local.target);local.attempts+=added.attempts;local.good+=added.good;added.errors.forEach(i=>local.errors.add(i));local.mistakes.push(...mistakeDetails(local.typed,next,local.target,{mode:effectivePunctuation(),kind:type==='word'&&state.sceneSpelling?'spelling':'character'}));local.typed=next;local.seconds=(performance.now()-local.started)/1000;paintInline(type);updateInline(type);if(chars(next).length>=chars(local.target).length)finishInline(type,'completed');}
