function reset(keepContext=true){if(session?.context?.kind==='daily'){beginDaily();return;}clearInterval(timer);if(!keepContext)state.context=null;prepare();state.page='articles';render();}
function navigate(page,writeURL=true){
 const url=new URL(location.href),dailyDocument=isDailyPath(url.pathname);
 if(page==='daily'&&!dailyDocument){url.pathname=documentPath(url.pathname,'daily');url.hash='';location.assign(url.href);return;}
 if(page!=='daily'&&dailyDocument){url.pathname=documentPath(url.pathname,page);url.hash=page==='articles'?'':page;location.assign(url.href);return;}
 stopInline();clearInterval(timer);document.body.classList.remove('typing');state.page=page;state.trainer=null;state.result=null;session=null;state.context=null;dailyPhase='home';if(page==='scenes')state.scene=null;if(page==='academy'){state.course=null;state.trainer=null;}if(page==='daily')dailyData=null;
 if(writeURL&&!dailyDocument)history.pushState({page},'',page==='articles'?url.pathname+url.search:url.pathname+url.search+'#'+page);render();if(page==='daily')loadDaily(true);
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.page){navigate(b.dataset.page);return;}
 if(b.dataset.setting){const key=b.dataset.setting;
  if(key==='ui'){state.ui=b.dataset.value;persist();if(state.page==='scenes'&&state.scene){renderSceneDetail(true);}else render();return;}
  if(key==='lang'&&state.page==='daily'){state.lang=b.dataset.value;persist();clearInterval(timer);session=null;state.context=null;state.result=null;dailyPhase='home';dailyData=null;loadDaily(true);return;}
  if(key==='historyLang'){state.historyLang=b.dataset.value;renderHistory();return;}
  state[key]=['seconds','length'].includes(key)?Number(b.dataset.value):b.dataset.value;persist();if(key!=='rule')state.context=null;state.result=null;
  if(state.page==='articles')reset();else if(state.page==='scenes'){state.sceneSpelling=false;render();}else render();return;
 }
 if(b.dataset.filter){state.sceneFilter=b.dataset.filter;renderScenes();return;}
 if(b.dataset.scene){state.scene=b.dataset.scene;state.sceneSets={word:0,sentence:0,passage:0};state.sceneSpelling=false;renderSceneDetail();return;}
 if(b.dataset.course){state.trainer=null;state.course=b.dataset.course;state.lesson=0;renderLesson();return;}
 if(b.dataset.lesson){state.lesson=Number(b.dataset.lesson);renderLesson();return;}
 if(b.dataset.inlineReset){const type=b.dataset.inlineReset;const local=inlineSessions[type];Object.assign(local,{typed:'',started:0,attempts:0,good:0,seconds:0,phase:'ready',samples:[],errors:new Set(),composing:false,mistakes:[],resultHTML:''});const input=$('#inline-input-'+type);input.value='';input.disabled=false;$('#inline-result-'+type).hidden=true;paintInline(type);updateInline(type);input.focus();return;}
 if(b.dataset.inlineFinish){finishInline(b.dataset.inlineFinish);return;}
 if(b.dataset.trainer){openTrainer(b.dataset.trainer);return;}
 if(b.dataset.candidate){chooseCandidate(b.dataset.candidate);return;}
 if(b.dataset.sceneNext){const type=b.dataset.sceneNext;state.sceneSets[type]=(state.sceneSets[type]+1)%(type==='passage'?2:3);renderSceneDetail(true);return;}
 const action=b.dataset.action;
 if(action==='trainer-check')checkCandidate();
 if(action==='trainer-hints'){state.trainer.showHint=!state.trainer.showHint;renderTrainer();}
 if(action==='back-trainer'){state.trainer=null;renderAcademy();}
 if(action==='trainer-article'){state.lang={pinyin:'zh',zhuyin:'tw',jyutping:'yue'}[state.trainer.method];persist();navigate('articles');}
 if(action==='weak-review')beginWeakReview(b.dataset.language);
 if(action==='reading-audit')auditReadings();
 if(action==='reading-save'&&collectReadingEdits()!==null){$('#dialog').close();$('#custom-diagnostics').outerHTML=customChecks();}
 if(action==='reading-add'){const at=Number($('#reading-position').value)-1;if(collectReadingEdits()!==null&&Number.isInteger(at)&&at>=0) auditReadings(at);}
 if(action==='reading-clear'){const d=drafts[state.lang];delete d.readingEdits;delete d.readingText;save('drafts',drafts);auditReadings();}
 if(action==='scene-hints'){if(state.lang==='yue')state.showJyutping=!state.showJyutping;else state.showSceneHints=!state.showSceneHints;persist();renderSceneDetail(true);}
 if(action==='settings')settings();
 if(action==='close-dialog'&&profile)$('#dialog').close();
 if(action==='history')navigate('history');
 if(action==='restart'||action==='retry'){if(state.page==='daily'){beginDaily();return;}if(action==='retry')state.context=state.result?.context||null;reset();$('#typing-input')?.focus();}
 if(action==='new'){state.context=null;if(state.mode==='custom')state.mode='length';drawNext();persist();reset();}
 if(action==='finish')finish('ended');
 if(action==='custom-limit'){
  const isTime=state.mode==='time';openDialog(t(isTime?'customTime':'customLength'),`<label class="dialog-row">${t(isTime?'seconds':state.lang==='en'?'words':'characters')}<input id="custom-value" type="number" min="${isTime?5:10}" max="${isTime?600:2000}" value="${isTime?state.seconds:state.length}"></label><p class="dialog-help">${isTime?'5–600':'10–2000'}</p><button class="btn primary" data-action="apply-custom">${t('save')}</button>`);
 }
 if(action==='apply-custom'){const n=Number($('#custom-value').value),isTime=state.mode==='time';if(!Number.isInteger(n)||n<(isTime?5:10)||n>(isTime?600:2000)){toast(t('invalid'));return;}state[isTime?'seconds':'length']=n;persist();$('#dialog').close();state.context=null;reset();}
 if(action==='custom-start'){const d=drafts[state.lang]||{},text=preparePassage(d.text||'');if(chars(text).length<2||chars(text).length>20000){toast(t('customEmpty'));return;}if(d.ending==='time'&&(!Number.isInteger(d.seconds)||d.seconds<5||d.seconds>600)){toast(t('invalid'));return;}state.context={kind:'custom',text,readingEdits:d.readingText===text?d.readingEdits||{}:{},title:d.title?.trim()||t('customDefault'),timed:d.ending==='time'};if(d.ending==='time')state.seconds=d.seconds;persist();reset();$('#typing-input')?.focus();}
 if(action==='custom-edit'){state.context=null;state.mode='custom';reset();}
 if(action==='exit-special'){state.context=null;state.mode='length';reset();}
 if(action==='daily')navigate('daily');
 if(action==='begin-daily')beginDaily();
 if(action==='daily-refresh')loadDaily(true);
 if(action==='retry-sync'&&state.result)syncDailyResult(state.result);
 if(action==='profile')openProfile(profile?'account':'welcome');
 if(action==='profile-rename')openProfile('rename');
 if(action==='profile-restore')openProfile('restore');
 if(action==='profile-create')openProfile('welcome');
 if(action==='profile-backup')openProfile('backup');
 if(action==='show-recovery'){const field=$('#recovery-display');field.type=field.type==='password'?'text':'password';b.textContent=t(field.type==='password'?'showRecovery':'hideRecovery');}
 if(action==='copy-recovery'){navigator.clipboard.writeText(online.identity.token).then(()=>toast(t('copied'))).catch(()=>toast(t('copyFailed')));}
 if(action==='review'){const r=state.result;if(state.page==='daily'){navigate('articles');return;}const sentences=r.target.match(r.lang==='en'?/[^.!?]+[.!?]+(?:\s|$)|[^.!?]+$/g:/[^。！？]+[。！？]+|[^。！？]+$/g)||[r.target];let at=0;const out=sentences.filter(part=>{const end=at+chars(part).length;const include=r.errors.some(i=>i>=at&&i<end);at=end;return include;}).join('');if(!out)return;state.context={kind:'review',text:out.trim(),title:t('reviewTitle')};state.mode='length';reset();}
 if(action==='back-scenes'){stopInline();state.scene=null;renderScenes();}
 if(action==='scene-hanzi'||action==='scene-spelling'){state.sceneSpelling=action==='scene-spelling';renderSceneDetail(true);}
 if(action==='back-academy'){state.course=null;state.trainer=null;renderAcademy();}
 if(action==='next-lesson'){const c=courses.find(c=>c.id===state.course);if(state.lesson<c.lessons.length-1){state.lesson++;renderLesson();}else{state.lang=c.lang;state.mode='length';persist();navigate('articles');toast(t('courseDone'));}}
 if(action==='clear-history')openDialog(t('clearHistory'),`<p class="dialog-help">${t('clearConfirm')}</p><div class="results-actions"><button class="btn" data-action="settings">${t('cancel')}</button><button class="btn" data-action="confirm-clear">${t('confirm')}</button></div>`);
 if(action==='confirm-clear'){records=records.filter(r=>r.userId!==profile?.id);save('history',records);$('#dialog').close();if(state.page==='history')renderHistory();}
});
document.addEventListener('change',e=>{if(e.target.id==='method-select'){state.methods={...state.methods,[state.lang]:e.target.value};persist();}if(e.target.id==='punctuation-select'){state.punctuation=e.target.value;persist();if(state.page==='scenes')renderSceneDetail();else reset();}if(e.target.matches('[data-jyutping-toggle]')){state.showJyutping=e.target.checked;persist();if(state.page==='academy'&&state.trainer)renderTrainer();else applyJyutpingDisplay();}});
document.addEventListener('keydown',e=>{if(state.page==='academy'&&state.trainer?.stage==='choose'&&!e.isComposing&&!$('#dialog').open&&/^[1-9]$/.test(e.key)){const choice=candidateLessons[state.trainer.method][state.trainer.index].candidates[Number(e.key)-1];if(choice){e.preventDefault();chooseCandidate(choice);}return;}if(e.isComposing||session?.composing)return;if(profile&&e.altKey&&e.key.toLowerCase()==='r'&&['articles','daily'].includes(state.page)){e.preventDefault();if($('#dialog').open)$('#dialog').close();reset();$('#typing-input')?.focus();}if(e.key==='Escape'&&profile&&!$('#dialog').open){e.preventDefault();settings();}});
$('#dialog').addEventListener('click',e=>{if(profile&&e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
$('#dialog').addEventListener('cancel',e=>{if(!profile)e.preventDefault();});
window.addEventListener('popstate',()=>{if(!isDailyPath(location.pathname))navigate(['scenes','academy','history'].includes(location.hash.slice(1))?location.hash.slice(1):'articles',false);});
if(!profile)openProfile('welcome');else online.refresh().then(user=>{profile=user;const name=$('.profile-name'),avatar=$('.profile-avatar');if(name)name.textContent=user.name;if(avatar)avatar.textContent=chars(user.name).slice(0,2).join('').toUpperCase();}).catch(error=>{if(error.code==='IDENTITY'){profile=null;online.clear();openProfile('restore');}});

function effectivePunctuation(){return state.page==='daily'||session?.context?.kind==='daily'?'strict':state.punctuation;}
function selectedMethod(){return methodFor(state.lang,state.methods);}
function languageControls(){const p=languageProfiles[state.lang];return `<div class="language-controls"><label>${t('inputMethod')}<select id="method-select" aria-label="${t('inputMethod')}">${p.methods.map(m=>`<option value="${m}" ${selectedMethod()===m?'selected':''}>${t(m+'Method')}</option>`).join('')}</select></label><label>${t('punctuation')}<select id="punctuation-select" aria-label="${t('punctuation')}">${['strict','compatible'].map(m=>`<option value="${m}" ${state.punctuation===m?'selected':''}>${t(m)}</option>`).join('')}</select></label><p>${t('languageInfo'+state.lang)}<br>${t('methodHint')}<br>${t('punctuationHelp')}</p></div>`;}
function saveMistakes(mistakes,{lang=state.lang,method=selectedMethod()}={}){if(!profile||!mistakes.length)return;weaknesses=recordWeaknesses(weaknesses,mistakes,{lang,userId:profile.id,method});save('weaknesses-v1',weaknesses);}
function weakMarkup(){const lang=state.historyLang==='all'?state.lang:state.historyLang;const due=dueWeaknesses(weaknesses,{userId:profile?.id,lang});return `<section class="weak-card"><div class="inline-heading"><h2>${t('weakTitle')}</h2><span>${languageNames[lang]} · ${due.length} ${t('weakDue')}</span></div><p>${t('weakHelp')}</p>${due.length?`<div class="weak-items">${due.map(e=>`<div><b>${esc(e.got)} → ${esc(e.expected)}</b><small>${t('weak'+e.kind[0].toUpperCase()+e.kind.slice(1))} · ${e.count} ${t('weakCount')}</small><span>${esc(e.phrase)}</span></div>`).join('')}</div><button class="btn primary" data-action="weak-review" data-language="${lang}">${t('weakBegin')}</button>`:`<p class="chart-note">${t('weakEmpty')}</p>`}</section>`;}
function beginWeakReview(lang){const entries=dueWeaknesses(weaknesses,{userId:profile?.id,lang});if(!entries.length)return;const kind=entries[0].kind,method=entries[0].method,group=entries.filter(e=>e.kind===kind&&e.method===method);state.lang=lang;state.mode='length';state.methods={...state.methods,[lang]:method};persist();navigate('articles');state.context={kind:'weak',text:[...new Set(group.map(e=>e.phrase))].join(lang==='en'||kind==='spelling'?' ':'\n').replace(/\n/g,' '),title:t('weakReview'),weakKeys:group.map(e=>e.key),spelling:kind==='spelling',method};prepare();render();$('#typing-input')?.focus();}
function candidateEntry(){return `<section class="candidate-entry"><div><h2>${t('trainer')}</h2><p>${t('trainerSub')}</p></div><div class="results-actions">${['pinyin','zhuyin','jyutping'].map(m=>`<button class="btn" data-trainer="${m}">${t(m+'Method')}</button>`).join('')}</div></section>`;}
function openTrainer(method){state.course=null;state.trainer={method,index:0,wrong:0,stage:'spell',showHint:true,value:'',feedback:''};renderTrainer();}
function renderTrainer(){const tr=state.trainer,steps=candidateLessons[tr.method],step=steps[tr.index];const yue=tr.method==='jyutping';
 shell(`<button class="back" data-action="back-trainer">${icon('back')}${t('back')}</button>`+heading('INPUT ACADEMY / CANDIDATES',t('trainer'),t('trainerSource'))+`${yue?jyutpingSwitch():''}<section class="candidate-trainer">${step?`<div class="eyebrow">${tr.index+1} / ${steps.length} · ${t(tr.method+'Method')}</div><div class="trainer-word"><span>${t('targetWord')}: ${markedText(step.meaning,{enabled:yue&&state.showJyutping})}</span><strong>${markedText(step.target,{enabled:yue&&state.showJyutping})}</strong></div><div class="trainer-hints"><button class="quiet-link" data-action="trainer-hints">${t(tr.showHint?'hideHints':'showHints')}</button>${tr.showHint?`<code>${esc(step.code.replace(/ $/,' + Space'))}</code>${tr.method==='zhuyin'?`<span>${esc(symbolsForKeys(step.code))}</span>`:''}`:''}</div><p>${t('trainerKeys')}</p>${tr.stage==='spell'?`<label for="candidate-input">${t('trainerSpell')}</label><input id="candidate-input" class="lesson-input" spellcheck="false" autocomplete="off" autocapitalize="off" value="${esc(tr.value)}"><button class="btn primary" data-action="trainer-check">${t('trainerCheck')}</button>`:`<h3>${t('trainerChoose')}</h3><div class="candidate-options">${step.candidates.map((word,i)=>`<button class="btn" data-candidate="${esc(word)}"><small>${i+1}</small>${markedText(word,{enabled:yue&&state.showJyutping})}</button>`).join('')}</div><p>${t('candidateHelp')}</p>`}<p id="candidate-feedback" class="lesson-status" role="status">${tr.feedback?esc(t(tr.feedback)):''}</p>`:`<h2>${t('trainerDone')}</h2><p>8 / 8 · ${tr.wrong} ${t('weakCount')}</p><div class="results-actions"><button class="btn primary" data-trainer="${tr.method}">${t('trainerAgain')}</button><button class="btn" data-action="trainer-article">${t('trainerToArticle')}</button></div>`}</section>`);
 const input=$('#candidate-input');if(input){input.oninput=()=>{tr.value=input.value;};input.onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();checkCandidate();}};input.focus();}
}
function checkCandidate(){const tr=state.trainer,step=candidateLessons[tr.method][tr.index],value=$('#candidate-input').value;tr.value=value;if(!checkSpelling(value,step,tr.method)){tr.feedback=step.code.startsWith(value.toLowerCase())?'trainerIncomplete':'trainerWrong';$('#candidate-feedback').textContent=t(tr.feedback);if(tr.feedback==='trainerWrong'){tr.wrong++;const lang={pinyin:'zh',zhuyin:'tw',jyutping:'yue'}[tr.method];saveMistakes(mistakeDetails('',value,step.code,{kind:'spelling'}),{lang,method:tr.method});}return;}tr.stage='choose';tr.feedback='';renderTrainer();$('.candidate-options button')?.focus();}
function chooseCandidate(word){const tr=state.trainer,step=candidateLessons[tr.method][tr.index];const next=nextCandidateState(tr,word,candidateLessons[tr.method]);if(next.feedback==='wrong'){tr.wrong=next.wrong;tr.feedback='candidateWrong';saveMistakes([{expected:step.target,got:word,phrase:step.target,kind:'selection'}],{lang:{pinyin:'zh',zhuyin:'tw',jyutping:'yue'}[tr.method],method:tr.method});$('#candidate-feedback').textContent=t('candidateWrong');return;}state.trainer={...next,stage:'spell',value:'',feedback:''};const key='candidates-'+tr.method;if(next.done){const done=lessonProgress[key]||[];if(!done.includes(0))done.push(0);lessonProgress[key]=done;save('lessons-v2',lessonProgress);}renderTrainer();}
function customChecks(){const d=drafts[state.lang]||{},inspection=inspectPassage(d.text||'');return `<div id="custom-diagnostics" class="custom-diagnostics">${inspection.issues.length?`<b>${t('customInspect')}</b><ul>${inspection.issues.map(k=>`<li>${t('issue'+k[0].toUpperCase()+k.slice(1))}</li>`).join('')}</ul>`:''}${state.lang==='yue'?`<button class="btn" data-action="reading-audit">${t('readingAudit')}</button><p>${t('readingHelp')}</p>`:''}</div>`;}
function auditReadings(addPosition=null){const d=drafts[state.lang]||{},text=preparePassage(d.text||'');if(!text){toast(t('customEmpty'));return;}const edits=d.readingText===text?{...d.readingEdits}:{};const details=readingDetails(text,{custom:true,edits}),letters=chars(text);const flagged=details.map((x,i)=>({...x,i})).filter(x=>['unknown','uncertain','user'].includes(x.source)).slice(0,60);if(addPosition!==null&&details[addPosition]&&!flagged.some(x=>x.i===addPosition))flagged.push({...details[addPosition],i:addPosition});
 openDialog(t('readingAudit'),`<p class="dialog-help">${t('readingHelp')}</p><div class="reading-audit-table"><table><thead><tr><th>${t('readingPosition')}</th><th>${t('jyutping')}</th></tr></thead><tbody>${flagged.map(x=>`<tr><td><b>${x.i+1}. ${esc(letters[x.i])}</b><small>${esc(letters.slice(Math.max(0,x.i-5),x.i+6).join(''))}</small><span>${t(x.source==='unknown'?'readingUnknown':x.source==='user'?'readingUser':'readingUncertain')}</span></td><td><input data-reading-index="${x.i}" aria-label="${esc(letters[x.i])} · ${x.i+1}" pattern="[a-z]*" value="${esc(edits[x.i]||'')}" placeholder="${esc(x.reading||'')}" list="reading-options-${x.i}"><datalist id="reading-options-${x.i}">${(alternativeReadings[letters[x.i]]||[]).map(r=>`<option value="${r}"></option>`).join('')}</datalist></td></tr>`).join('')}</tbody></table></div><p class="dialog-help">${t('readingLimit')}</p><label class="dialog-row">${t('readingIndex')}<input id="reading-position" type="number" min="1" max="${letters.length}" value="1"></label><div class="results-actions"><button class="btn" data-action="reading-add">${t('readingEditAdd')}</button><button class="btn" data-action="reading-clear">${t('readingClear')}</button><button class="btn primary" data-action="reading-save">${t('readingSaved')}</button></div><p id="reading-error" role="alert"></p>`);
}
function collectReadingEdits(){const d=drafts[state.lang]||{},text=preparePassage(d.text||'');let edits=d.readingText===text?{...d.readingEdits}:{};for(const input of document.querySelectorAll('[data-reading-index]')){const reading=input.value.trim().toLowerCase();if(reading&&(!/^[a-z]+$/.test(reading)||!validJyutpingReading(reading))){$('#reading-error').textContent=t('readingInvalid');return null;}if(reading)edits[input.dataset.readingIndex]=reading;else delete edits[input.dataset.readingIndex];}drafts[state.lang]={...d,readingText:text,readingEdits:edits};save('drafts',drafts);return edits;}
